import numpy as np

class MolecularGNN:
    def __init__(self, atom_dim, bond_dim, hidden_dim, num_tasks):
        self.hidden_dim = hidden_dim
        self.num_tasks = num_tasks
        self.W_atom = np.random.randn(atom_dim, hidden_dim) * 0.01
        self.W_bond = np.random.randn(bond_dim, hidden_dim) * 0.01
        self.W_msg = np.random.randn(hidden_dim, hidden_dim) * 0.01
        self.W_update = np.random.randn(2*hidden_dim, hidden_dim) * 0.01
        self.W_readout = np.random.randn(3*hidden_dim, hidden_dim) * 0.01
        self.W_predict = np.random.randn(hidden_dim, num_tasks) * 0.01
    def encode_atoms(self, atom_features):
        return np.maximum(0, atom_features @ self.W_atom)
    def encode_bonds(self, bond_features):
        return np.maximum(0, bond_features @ self.W_bond)
    def message_pass(self, H, edge_index, bond_enc):
        H_new = np.zeros_like(H)
        src, dst = edge_index
        for i in range(len(src)):
            msg = H[src[i]] @ self.W_msg + bond_enc[i]
            H_new[dst[i]] += msg
        for v in range(len(H)):
            concat = np.concatenate([H[v], H_new[v]])
            H_new[v] = np.maximum(0, concat @ self.W_update)
        return H_new
    def readout(self, H):
        h_sum = np.sum(H, axis=0)
        h_mean = np.mean(H, axis=0)
        h_max = np.max(H, axis=0)
        h_graph = np.concatenate([h_sum, h_mean, h_max])
        return np.maximum(0, h_graph @ self.W_readout)
    def predict(self, h_graph):
        return h_graph @ self.W_predict
    def forward(self, atom_features, bond_features, edge_index, num_message_steps=3):
        H = self.encode_atoms(atom_features)
        bond_enc = self.encode_bonds(bond_features)
        for _ in range(num_message_steps):
            H = self.message_pass(H, edge_index, bond_enc)
        h_graph = self.readout(H)
        return self.predict(h_graph)
